// Parse Cathay United Bank spending summary email HTML
// Extracts individual transactions from the consolidated daily email

const items = [];

for (const item of $input.all()) {
  const html = item.json.textHtml || '';
  const emailDate = item.json.date;
  const messageId = item.json.id;

  // Extract transaction rows from .spend_table elements
  // Cathay emails use HTML tables with class 'spend_table'
  // Each table contains: date, merchant, amount, card last 4 digits
  const tableRegex = /class=["']spend_table["'][^>]*>(.*?)<\/table>/gis;
  const rowRegex = /<tr[^>]*>(.*?)<\/tr>/gis;
  const cellRegex = /<td[^>]*>(.*?)<\/td>/gis;

  // Fallback: if no .spend_table, try to parse any structured transaction data
  let tables = [...html.matchAll(tableRegex)];

  if (tables.length === 0) {
    // Alternative pattern: look for transaction-like content in generic tables
    // Cathay emails may also use inline styles instead of classes
    const altTableRegex = /<table[^>]*>(.*?)<\/table>/gis;
    tables = [...html.matchAll(altTableRegex)];
  }

  for (const table of tables) {
    const tableHtml = table[1] || table[0];
    const rows = [...tableHtml.matchAll(rowRegex)];

    for (const row of rows) {
      const rowHtml = row[1] || row[0];
      const cells = [...rowHtml.matchAll(cellRegex)];
      const cellValues = cells.map(c => {
        // Strip HTML tags and decode entities
        return (c[1] || '')
          .replace(/<[^>]*>/g, '')
          .replace(/&nbsp;/g, ' ')
          .replace(/&amp;/g, '&')
          .replace(/&lt;/g, '<')
          .replace(/&gt;/g, '>')
          .replace(/&#\d+;/g, '')
          .trim();
      });

      // Skip header rows and empty rows
      if (cellValues.length < 3) continue;
      if (cellValues.some(v => /日期|時間|交易|Date/i.test(v))) continue;

      // Try to identify transaction fields
      // Common patterns: [date, merchant, amount] or [date, merchant, amount, card]
      let txDate = null;
      let merchant = null;
      let amount = null;
      let cardLast4 = null;

      for (const val of cellValues) {
        // Date pattern: YYYY/MM/DD or MM/DD or YYYY-MM-DD
        if (!txDate && /\d{2,4}[\/\-]\d{1,2}[\/\-]\d{1,2}/.test(val)) {
          txDate = val;
        }
        // Amount pattern: numbers with optional comma/decimal, possibly with NT$ or TWD
        else if (!amount && /[\d,]+\.?\d*/.test(val) && /\d{2,}/.test(val.replace(/,/g, ''))) {
          amount = val.replace(/[^\d.\-]/g, '');
        }
        // Card last 4 digits
        else if (!cardLast4 && /^\d{4}$/.test(val.trim())) {
          cardLast4 = val.trim();
        }
        // Merchant name: whatever's left that isn't a number or date
        else if (!merchant && val.length > 1 && !/^[\d\s.,\/\-]+$/.test(val)) {
          merchant = val;
        }
      }

      if (amount && (merchant || txDate)) {
        items.push({
          json: {
            messageId,
            emailDate,
            transactionDate: txDate || emailDate,
            merchant: merchant || 'Unknown',
            amount: parseFloat(amount),
            cardLast4: cardLast4 || '',
            rawCells: cellValues
          }
        });
      }
    }
  }
}

if (items.length === 0) {
  items.push({
    json: {
      error: 'No transactions parsed from email(s)',
      emailCount: $input.all().length
    }
  });
}

return items;

// Transform parsed Cathay transactions into YNAB API format
// YNAB uses milliunits: 1 TWD = 1000 milliunits
// Spending is negative (outflow)

// Configuration - UPDATE THESE VALUES
const YNAB_ACCOUNT_ID = '{{ $env.YNAB_ACCOUNT_ID || "CONFIGURE_ME" }}';

const transactions = [];

for (const item of $input.all()) {
  const tx = item.json;

  // Parse and normalize the date to ISO 8601 (YYYY-MM-DD)
  let isoDate;
  const dateStr = tx.transactionDate || '';

  if (/\d{4}[\/\-]\d{1,2}[\/\-]\d{1,2}/.test(dateStr)) {
    // YYYY/MM/DD or YYYY-MM-DD
    const parts = dateStr.split(/[\/\-]/);
    isoDate = `${parts[0]}-${parts[1].padStart(2, '0')}-${parts[2].padStart(2, '0')}`;
  } else if (/\d{1,2}[\/\-]\d{1,2}[\/\-]\d{4}/.test(dateStr)) {
    // MM/DD/YYYY
    const parts = dateStr.split(/[\/\-]/);
    isoDate = `${parts[2]}-${parts[0].padStart(2, '0')}-${parts[1].padStart(2, '0')}`;
  } else {
    // Fallback to email date
    const d = new Date(tx.emailDate);
    isoDate = d.toISOString().split('T')[0];
  }

  // Convert amount to milliunits (negative for outflows/spending)
  const milliunits = Math.round(tx.amount * -1000);

  // Build memo from card info
  const memo = tx.cardLast4 ? `Card: ****${tx.cardLast4}` : '';

  // Generate import_id for deduplication
  // Format: YNAB:milliunit_amount:iso_date:occurrence
  // Count occurrences of same amount on same date for the occurrence number
  const baseImportId = `YNAB:${milliunits}:${isoDate}`;
  const occurrence = transactions.filter(t =>
    t.import_id && t.import_id.startsWith(baseImportId)
  ).length + 1;

  transactions.push({
    account_id: YNAB_ACCOUNT_ID,
    date: isoDate,
    amount: milliunits,
    payee_name: tx.merchant,
    memo: memo,
    cleared: 'cleared',
    import_id: `${baseImportId}:${occurrence}`
  });
}

return [{
  json: {
    transactions: transactions
  }
}];
